import type { Mock } from "vitest";
import type { H3Config, H3Event, NodeHandler, HTTPError } from "../src/index.ts";
import { tracingPlugin } from "../src/tracing.ts";
import { Server as NodeServer } from "node:http";
import { getRandomPort } from "get-port-please";
import { beforeEach, afterEach, vi, it, describe, expect, beforeAll, afterAll } from "vitest";
import { H3 } from "../src/index.ts";
import { toNodeHandler } from "../src/_entries/node.ts";

// Matrix
export function describeMatrix(
  title: string,
  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
  opts?: TestOptions,
): void {
  const run = (ctx: TestContext) => {
    const utils: TestUtils = {
      expect,
      describe,
      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
        only: interceptFnWithSuffix(it.only, ctx.target),
        todo: interceptFnWithSuffix(it.todo, ctx.target),
        skip: interceptFnWithSuffix(it.skip, ctx.target),
        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
      }),
    };
    fn(ctx, utils);
  };
  describe(title, () => {
    describe("web", () => {
      run(setupWebTest(opts));
    });
    describe("node", () => {
      run(setupNodeTest(opts));
    });
  });
}

// Web
function setupWebTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("web", opts);
  beforeEach(() => {
    ctx.fetch = (input, init) => {
      const headers = new Headers(init?.headers);
      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
        headers.set("Host", "localhost");
      }
      return Promise.resolve(
        ctx.app.request(input, {
          ...init,
          headers,
        }),
      );
    };
  });
  return ctx;
}

// Node.js
function setupNodeTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("node", opts);

  let server: NodeServer;
  let handler: NodeHandler;

  beforeAll(async () => {
    server = new NodeServer((req, res) => {
      handler!(req, res);
    });
    const port = await getRandomPort();
    await new Promise<void>((resolve) => server.listen(port, resolve));
    ctx.url = `http://localhost:${port}`;
    ctx.fetch = (input, init = {}) => {
      const url = new URL(input, ctx.url);
      const headers = new Headers(init.headers);
      // Emulate a reverse proxy
      if (!headers.has("host")) {
        headers.set("Host", url.host);
      }
      if (!headers.has("x-forwarded-host")) {
        headers.set("X-Forwarded-Host", url.host);
      }
      if (url.protocol === "https:" && !headers.has("x-forwarded-proto")) {
        headers.set("X-Forwarded-Proto", "https");
      }
      return fetch(`${ctx.url}${url.pathname}${url.search}`, {
        redirect: "manual",
        // @ts-expect-error undici/node specific
        duplex: "half",
        ...init,
        headers,
      });
    };
  });

  afterAll(async () => {
    server.closeAllConnections();
    await new Promise<void>((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve())),
    );
    server = undefined!;
  });

  beforeEach(async () => {
    handler = toNodeHandler(ctx.app);
  });

  afterEach(() => {
    handler = undefined!;
  });

  return ctx;
}

// Base
function setupBaseTest(target: TestContext["target"], opts: TestOptions = {}): TestContext {
  const ctx: TestContext = { target } as TestContext;

  beforeEach(async () => {
    ctx.hooks = {
      onRequest: vi.fn(),
      onError: vi.fn(),
      onResponse: vi.fn(),
    };

    ctx.errors = [];
    ctx.hooks.onError.mockImplementation((error, _event: H3Event) => {
      if (opts.debug) {
        console.error(error);
      }
      ctx.errors.push(error);
    });

    ctx.app = new H3({
      debug: true,
      onError: ctx.hooks.onError,
      onRequest: ctx.hooks.onRequest,
      onResponse: ctx.hooks.onResponse,
      plugins: [opts.tracing ? tracingPlugin() : undefined].filter((p) => !!p),
    });
  });

  afterEach(async () => {
    const errors = ctx.errors;

    ctx.app = undefined!;
    ctx.hooks = undefined!;
    ctx.errors = undefined!;

    vi.resetAllMocks();
    if (!opts.allowUnhandledErrors) {
      const unhandledErrors = errors.filter((error) => error.unhandled);
      if (unhandledErrors.length > 0) {
        throw mergeErrors(errors);
      }
    }
  });

  return ctx;
}

// --- types ---

export interface TestOptions {
  allowUnhandledErrors?: boolean;
  startServer?: boolean;
  debug?: boolean;
  tracing?: boolean;
}

export interface TestContext {
  errors: HTTPError[];
  hooks: {
    onRequest: Mock<Exclude<H3Config["onRequest"], undefined>>;
    onError: Mock<Exclude<H3Config["onError"], undefined>>;
    onResponse: Mock<Exclude<H3Config["onResponse"], undefined>>;
  };

  target: "web" | "node";
  app: H3;
  url?: string;
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
}

export interface TestUtils {
  it: typeof it;
  describe: typeof describe;
  expect: typeof expect;
}

// --- utils ---

function mergeErrors(err: Error | Error[]) {
  if (Array.isArray(err)) {
    if (err.length === 1) {
      return mergeErrors(err[0]);
    }
    return new Error(
      "[tests] H3 global errors: \n" + err.map((error) => " - " + (error.stack || "")).join("\n"),
    );
  }
  return new Error("[tests] H3 global error: " + (err.stack || ""));
}

function interceptFnWithSuffix<T extends (...args: any[]) => any>(
  originalFn: T,
  suffix: string,
): T {
  return Object.assign((...args: Parameters<T>) => {
    args[0] += ` (${suffix})`;
    return originalFn(...args);
  }, originalFn);
}

import { sanitizeStatusMessage, sanitizeStatusCode } from "./utils/sanitize.ts";

/**
 * Raw object describing HTTP error (passed to `HTTPError` constructor).
 */
export interface ErrorInput<DataT = unknown> extends Partial<ErrorBody<DataT>> {
  /**
   * Original error object that caused this error.
   */
  cause?: unknown;

  /**
   * Additional HTTP headers to be sent in error response.
   */
  headers?: HeadersInit;

  /**
   * @deprecated use `status`
   */
  statusCode?: number;

  /**
   * @deprecated use `statusText`
   */
  statusMessage?: string;
}

export type ErrorDetails = (Error & { cause?: unknown }) | HTTPError | ErrorInput;

export interface ErrorBody<DataT = unknown> {
  /**
   * HTTP status code in range [200...599]
   */
  status: number;

  /**
   * HTTP status text
   *
   * **NOTE:** This should be short (max 512 to 1024 characters).
   * Allowed characters are tabs, spaces, visible ASCII characters, and extended characters (byte value 128–255).
   *
   * **TIP:** Use `message` for longer error descriptions in JSON body.
   */
  statusText?: string;

  /**
   * HTTP Error message.
   *
   * **NOTE:** This message will be in JSON body under `message` key.
   */
  message: string;

  /**
   * Flag to indicate that the error was not handled by the application.
   *
   * Unhandled error stack trace, `data`, `body` and `message` are hidden for security reasons.
   */
  unhandled?: boolean;

  /**
   * Additional data to attach in the error JSON body under `data` key.
   */
  data?: DataT;

  /**
   * Additional top level JSON body properties to attach in the error JSON body.
   */
  body?: Record<string, unknown>;
}

/**
 * HTTPError
 */
export class HTTPError<DataT = unknown> extends Error implements ErrorBody<DataT> {
  override get name(): string {
    return "HTTPError";
  }

  /**
   * HTTP status code in range [200...599]
   */
  readonly status: number;

  /**
   * HTTP status text
   *
   * **NOTE:** This should be short (max 512 to 1024 characters).
   * Allowed characters are tabs, spaces, visible ASCII characters, and extended characters (byte value 128–255).
   *
   * **TIP:** Use `message` for longer error descriptions in JSON body.
   */
  readonly statusText: string | undefined;

  /**
   * Additional HTTP headers to be sent in error response.
   */
  readonly headers: Headers | undefined;

  /**
   * Original error object that caused this error.
   */
  override readonly cause: unknown | undefined;

  /**
   * Additional data attached in the error JSON body under `data` key.
   */
  readonly data: DataT | undefined;

  /**
   * Additional top level JSON body properties to attach in the error JSON body.
   */
  readonly body: Record<string, unknown> | undefined;

  /**
   * Flag to indicate that the error was not handled by the application.
   *
   * Unhandled error stack trace, data and message are hidden in non debug mode for security reasons.
   */
  readonly unhandled: boolean | undefined;

  /**
   * Check if the input is an instance of HTTPError using its constructor name and status.
   *
   * It is safer than using `instanceof` because it works across different contexts (e.g., if the error was thrown in a different module).
   *
   * Requiring a `status` rejects unrelated errors named `HTTPError` (e.g. from fetch clients like `ky` or `got`), while
   * still accepting HTTPError-shaped errors from other packages (e.g. srvx `BodyTooLargeError`).
   */
  static override isError(input: any): input is HTTPError {
    return (
      input instanceof Error && input?.name === "HTTPError" && (input as HTTPError).status > 99
    );
  }

  /**
   * Create a new HTTPError with the given status code and optional status text and details.
   *
   * @example
   *
   * HTTPError.status(404)
   * HTTPError.status(418, "I'm a teapot")
   * HTTPError.status(403, "Forbidden", { message: "Not authenticated" })
   */
  static status(
    status: number,
    statusText?: string,
    details?: Exclude<ErrorDetails, "status" | "statusText" | "statusCode" | "statusMessage">,
  ): HTTPError {
    return new HTTPError({ ...details, statusText, status });
  }

  /**
   * Create a new HTTPError with the given message and optional details.
   *
   * @example
   *
   * new HTTPError("This is an error", { status: 400, cause: error })
   * new HTTPError({ message: "This is an error", status: 500, statusText: "Not Found", data: {} })
   */
  constructor(message: string, details?: ErrorDetails);
  constructor(details: ErrorDetails);
  constructor(arg1: string | ErrorDetails, arg2?: ErrorDetails) {
    let messageInput: string | undefined;
    let details: ErrorDetails | undefined;
    if (typeof arg1 === "string") {
      messageInput = arg1;
      details = arg2;
    } else {
      details = arg1;
    }

    const status = sanitizeStatusCode(
      (details as ErrorBody)?.status ||
        (details as ErrorInput)?.statusCode ||
        (details?.cause as ErrorBody)?.status ||
        (details?.cause as ErrorInput)?.statusCode,
      500,
    );

    const statusText = sanitizeStatusMessage(
      (details as ErrorBody)?.statusText ||
        (details as ErrorInput)?.statusMessage ||
        (details?.cause as ErrorBody)?.statusText ||
        (details?.cause as ErrorInput)?.statusMessage,
    );

    const message: string =
      messageInput ||
      details?.message ||
      (details?.cause as ErrorDetails)?.message ||
      (details as ErrorBody)?.statusText ||
      (details as ErrorInput)?.statusMessage ||
      ["HTTPError", status, statusText].filter(Boolean).join(" ");

    // @ts-ignore https://v8.dev/features/error-cause
    super(message, { cause: details });
    this.cause = details;

    this.status = status;
    this.statusText = statusText || undefined;

    const rawHeaders = (details as ErrorInput)?.headers || (details?.cause as ErrorInput)?.headers;
    this.headers = rawHeaders ? new Headers(rawHeaders) : undefined;

    this.unhandled =
      (details as ErrorBody)?.unhandled ?? (details?.cause as ErrorBody)?.unhandled ?? undefined;

    this.data = (details as ErrorBody)?.data as DataT | undefined;
    this.body = (details as ErrorBody)?.body;
  }

  /**
   * @deprecated Use `status`
   */
  get statusCode(): number {
    return this.status;
  }

  /**
   * @deprecated Use `statusText`
   */
  get statusMessage(): string | undefined {
    return this.statusText;
  }

  toJSON(): Omit<ErrorBody, "body"> & ErrorBody["body"] {
    const unhandled = this.unhandled;
    return {
      status: this.status,
      statusText: this.statusText,
      unhandled: unhandled,
      message: unhandled ? "HTTPError" : this.message,
      data: unhandled ? undefined : this.data,
      ...(unhandled ? undefined : this.body),
    };
  }
}

